alter table public.schoolpro_admissions add column if not exists public_token uuid not null default gen_random_uuid(),add column if not exists submitted_at timestamptz,add column if not exists accepted_at timestamptz;create unique index if not exists schoolpro_admissions_public_token_uq on public.schoolpro_admissions(public_token);
alter table public.schoolpro_cbt_tests add column if not exists instructions text,add column if not exists opens_at timestamptz,add column if not exists closes_at timestamptz,add column if not exists randomize_questions boolean not null default false,add column if not exists randomize_options boolean not null default false,add column if not exists attempts_allowed int not null default 1,add column if not exists test_type text not null default 'internal';
create table if not exists public.schoolpro_candidate_cbt_attempts(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.schoolpro_admissions(id) on delete cascade,test_id uuid not null references public.schoolpro_cbt_tests(id) on delete cascade,started_at timestamptz not null default now(),submitted_at timestamptz,score numeric,status text not null default 'in_progress',unique(application_id,test_id));
create table if not exists public.schoolpro_candidate_cbt_answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.schoolpro_candidate_cbt_attempts(id) on delete cascade,question_id uuid not null references public.schoolpro_question_bank(id),answer text,is_correct boolean,marks_awarded numeric not null default 0,unique(attempt_id,question_id));
alter table public.schoolpro_candidate_cbt_attempts enable row level security;alter table public.schoolpro_candidate_cbt_answers enable row level security;grant select,insert,update on public.schoolpro_candidate_cbt_attempts,public.schoolpro_candidate_cbt_answers to authenticated;
